shaderSource:
uniform float2 resolution;
uniform float tiltX;
uniform float tiltY;

half4 main(float2 xy) {
  float2 uv = xy / max(resolution, float2(1.0, 1.0));
  float aspect = resolution.x / max(resolution.y, 1.0);
  float2 light = float2(0.28, 0.16) + float2(tiltX, tiltY) * 0.24;

  float2 e = min(uv, 1.0 - uv);
  float rim = 1.0 - smoothstep(0.0, 0.10, min(e.x * aspect, e.y));
  float inset = smoothstep(0.0, 0.14, min(e.x * aspect, e.y));

  float body = 0.10 + 0.10 * (1.0 - uv.y);
  body += rim * 0.28;
  body *= mix(1.15, 0.75, smoothstep(0.45, 1.0, uv.y));

  float2 d = uv - light;
  d.x *= aspect;
  float spec = exp(-dot(d, d) * 16.0);
  float soft = exp(-dot(d, d) * 4.5);
  float sheen = smoothstep(0.0, 0.07, uv.y) * (1.0 - smoothstep(0.07, 0.36, uv.y));

  half3 tint = half3(0.86, 0.92, 1.0);
  float glow = body * 0.55 + spec * 0.72 + soft * 0.18 + sheen * 0.22;
  glow *= inset;

  float seam = smoothstep(0.92, 1.0, uv.y) * 0.18;
  glow = max(glow - seam, 0.0);

  return half4(tint, clamp(glow, 0.0, 0.85));
}
